  SELECT env_metrics, '{}'::text as path
  FROM environmentalmonitoring LIMIT 1
)
SELECT * FROM json_tree;

SELECT ROUND(
    100.0 * COUNT(*) FILTER (WHERE (em.env_metrics->'light_and_shock'->>'shock_event_count')::integer > 0) / COUNT(*),
    2
) as percentage
FROM shipments s
LEFT JOIN environmentalmonitoring em ON s.reckey = em.reckeylink;

SELECT ROUND(
    (COUNT(*) FILTER (WHERE (em.env_metrics->'light_and_shock'->>'shock_event_count')::integer > 0))::numeric / COUNT(*) * 100,
    2
) as percentage
FROM shipments s
LEFT JOIN environmentalmonitoring em ON s.reckey = em.reckeylink;
